INSERT INTO `theses` VALUES (1,'html thesis','Prof felix busching','<td><input type=\"text\" class=\"search-input\" data-column=\"1\" placeholder=\"🔍\"></td>\r\n<td><input type=\"text\" class=\"search-input\" data-column=\"2\" placeholder=\"🔍\"></td>\r\n<td><input type=\"text\" class=\"search-input\" data-column=\"3\" placeholder=\"🔍\"></td>\r\n<td><input type=\"text\" class=\"search-input\" data-column=\"4\" placeholder=\"🔍\"></td>\r\n<td><input type=\"text\" class=\"search-input\" data-column=\"5\" placeholder=\"🔍\"></td>','code',NULL,NULL,'Angebot','no',NULL,NULL,NULL,5,'2025-01-12 01:21:57','2025-03-07 19:00:37','thesis_pdfs/fA2iViDM8JLSVj7aqFe9mXmYxfigEeqmIlCtUhee.pdf',NULL,'[\"Teamprojekt\", \"Studienarbeit\", \"Bachelorthesis\"]'),(2,'datenbanken','Prof felix busching','Lorem ipsum dolor sit amet, consectetur adipiscing elit. Duis at dictum velit. Suspendisse potenti. In sit amet cursus lorem. Donec ac felis nec nunc ultricies volutpat nec et nisl. Ut venenatis tellus non mi:\r\n- Ultrices, ut laoreet risus dictum.\r\n- Vivamus mattis felis vitae ante lobortis\r\n- Tincidunt at rhoncus libero. Vestibulum vestibulum eros vel eros ornare, eu fringilla magna finibus. Aliquam efficitur lobortis ullamcorper. Nunc justo libero, bibendum quis rhoncus eget, condimentum vel quam. Maecenas vehicula magna ut erat suscipit, eget tristique neque tincidunt. Duis tempus euismod luctus. Suspendisse egestas lectus non eros consec','#Datenbanken #SQL',NULL,NULL,'Fertig','yes',NULL,NULL,NULL,5,'2025-01-12 01:22:32','2025-03-05 22:35:29','thesis_pdfs/CzUarlp40PzSVaS8tMdz8RrGPfmgCPOH6ZFUSrn7.pdf',NULL,'[\"Teamprojekt\", \"Bachelorthesis\", \"Masterthesis\"]'),(5,'Machine Learning in Healthcare geändert','Prof. Andreas Simon','Erforschung von Machine-Learning-Modellen zur Diagnose von Krankheiten.\r\nFokus auf Bilddaten aus der Radiologie.\r\nZiel: Verbesserung der Frühdiagnose bei chronischen Erkrankungen.\r\n\r\nErforschung von Machine-Learning-Modellen zur Diagnose von Krankheiten.\r\nFokus auf Bilddaten aus der Radiologie.\r\nZiel: Verbesserung der Frühdiagnose bei chronischen Erkrankungen.','Python TensorFlow Machine Learning Computer Vision','Ziel: Verbesserung der Frühdiagnose bei chronischen Erkrankungen.\r\n\r\nErforschung von Machine-Learning-Modellen zur Diagnose von Krankheiten.\r\nFokus auf Bilddaten aus der Radiologie.\r\nZiel: Verbesserung der Frühdiagnose bei chronischen Erkrankungen.','SS2025','Aktiv','yes','2022-11-10','2022-11-10','2023-11-10',10,'2025-01-23 21:03:07','2025-04-03 22:06:54',NULL,'thesis_pdfs/mFA422SQ2baaQ1dyxoNgFfydyba7sPVYREnupS6H.pdf','[\"Teamprojekt\"]'),(6,'Blockchain-basierte Lösungen für sichere Transaktionen','Prof. Andreas Simon','Sicherheit und Datenschutz bei Transaktionen.\r\nEntwicklung eines PoC für Finanztransaktionen.\r\nImplementierung einer Wallet-Anwendung.','Blockchain Solidity Ethereum Kryptographie',NULL,'WS','Fertig','no',NULL,'2020-11-10',NULL,10,'2025-01-23 21:04:59','2025-04-04 18:16:03','thesis_pdfs/SkgVHMNoKxYo1bb29dKXJCL3X8B1tQcQpOl3VYLW.pdf',NULL,'[\"Teamprojekt\"]'),(7,'Entwicklung von Big-Data-Analyse-Tools','Prof. Andreas Simon','Untersuchung großer Datensätze aus der Medizinbranche.\r\nNutzung von Hadoop und Spark für verteilte Verarbeitung.\r\nErstellung von interaktiven Dashboards zur Visualisierung.','Hadoop Spark Python Datenanalyse Visualisierung Verarbeitung Medizin Entwicklung Big-Data  Analyse-Tools','Untersuchung großer Datensätze aus der Medizinbranche.\r\nNutzung von Hadoop und Spark für verteilte Verarbeitung.\r\nErstellung von interaktiven Dashboards zur Visualisierung.Untersuchung großer Datensätze aus der Medizinbranche.\r\nNutzung von Hadoop und Spark für verteilte Verarbeitung.\r\nErstellung von interaktiven Dashboards zur Visualisierung.','WS2025','Fertig','no','2024-02-05','2024-02-02','2024-02-04',10,'2025-01-23 21:06:24','2025-04-02 12:04:02','thesis_pdfs/4qOTPRgjfbnVGZWAQGshXcM4vDlq2KmsEauZokKG.pdf',NULL,'[\"Studienarbeit\"]'),(8,'Anwendung von IoT-Geräten zur Smart-Home-Automatisierung','Prof. Andreas Simon','Konzeption eines Systems zur Steuerung von Smart-Home-Geräten.\r\nImplementierung mit Raspberry Pi und Arduino.\r\nIntegration von Sicherheitsprotokollen für Netzwerke.','#IoT #Raspberry Pi #Arduino #Netzwerkprotokolle',NULL,NULL,'Angebot','no',NULL,NULL,NULL,10,'2025-01-23 21:06:40','2025-04-02 12:04:02','thesis_pdfs/ZQg3g8fYzaRZ8PSw7lB18AGb9vSPLcrj7T6bjaEr.pdf',NULL,'[\"Teamprojekt\", \"Masterthesis\"]'),(57,'Einsatz von Künstlicher Intelligenz zur Optimierung von Produktionsprozessen in der Industrie 4.0','Prof. Andreas Simon','Die Digitalisierung und Automatisierung von Produktionsprozessen spielen eine zentrale Rolle in der Industrie 4.0. In dieser Arbeit wird untersucht, wie Künstliche Intelligenz (KI) zur Effizienzsteigerung in der Produktion beitragen kann. Dabei werden verschiedene KI-Technologien, wie maschinelles Lernen und Predictive Maintenance, analysiert und deren Potenziale aufgezeigt. Ziel der Arbeit ist es, praxisnahe Lösungsansätze zu entwickeln, um Produktionsabläufe zu optimieren, Kosten zu senken und Ressourcen effizienter zu nutzen.','Künstlicher-Intelligenz Programmierkenntnisse  Produktionsprozesse Datenanalyse',NULL,NULL,'Fertig','no',NULL,NULL,NULL,10,'2025-03-02 13:46:59','2025-04-02 12:04:02','thesis_pdfs/WQgxPFzl6T2oyEV6fE7rki7Pns1LbxEQ8SAbQDAM.pdf',NULL,'[\"Teamprojekt\"]'),(58,'Automatisierte Bilderkennung für die Qualitätssicherung in der Produktion','Prof. Andreas Simon','Moderne Produktionsprozesse erfordern eine zuverlässige Qualitätssicherung. In dieser Arbeit wird erforscht, wie Bilderkennungstechnologien mithilfe von Deep Learning zur automatischen Fehlererkennung in der Fertigung eingesetzt werden können. Ziel ist die Entwicklung eines Prototyps zur Klassifizierung und Identifikation von fehlerhaften Produkten.','Computer-Vision Qualitätssicherungsprozesse Neural-Networks',NULL,NULL,'Angebot','no',NULL,NULL,NULL,10,'2025-03-02 13:50:02','2025-04-02 12:04:02','thesis_pdfs/keUk1HxEyY42RhUB3G9mMYjZMhFE049Ta43Uh705.pdf',NULL,'[\"Teamprojekt\", \"Studienarbeit\", \"Bachelorthesis\", \"Masterthesis\"]'),(59,'Energieeffiziente Smart-Home-Systeme mit IoT und KI','Prof. Andreas Simon','Der Energieverbrauch in Haushalten kann durch intelligente Systeme optimiert werden. Diese Arbeit untersucht, wie IoT-Technologien und KI-Algorithmen genutzt werden können, um den Energieverbrauch zu analysieren und automatisiert zu reduzieren. Ziel ist es, ein Modell für ein intelligentes Smart-Home-System zu entwerfen, das Echtzeit-Daten auswertet und optimale Steuerungsmechanismen vorschlägt.','IoT  Raspberry-Pi Arduino Python MQTT-Broker',NULL,NULL,'Idle','no',NULL,NULL,NULL,10,'2025-03-02 13:53:28','2025-04-02 12:04:02','thesis_pdfs/gd4wCEKhl2jFC7mtytZuoOiAtYMZk1xzHbYWFF8W.pdf','thesis_pdfs/BPqR6lUIhjgn4AfssRu2ezzOPUFQLflk133pptCh.pdf','[\"Teamprojekt\", \"Studienarbeit\", \"Bachelorthesis\"]'),(61,'Test neu status','Prof. Andreas Simon','semesterTypeSelect.addEventListener(\'change\', handleSemesterTypeChange);\r\nwindow.addEventListener(\'DOMContentLoaded\', handleSemesterTypeChange);','semester',NULL,NULL,'Angebot','no',NULL,NULL,NULL,10,'2025-03-05 20:05:16','2025-04-02 12:04:02',NULL,NULL,'[\"Teamprojekt\", \"Studienarbeit\", \"Bachelorthesis\", \"Masterthesis\"]'),(62,'test Geheim Thesis','Prof. Andreas Simon','This Thesis is a Geheim Thesis\r\nThis Thesis is a Geheim Thesis\r\nThis Thesis is a Geheim Thesis\r\nThis Thesis is a Geheim Thesis\r\nThis Thesis is a Geheim Thesis','Geheim',NULL,NULL,'Angebot','yes',NULL,NULL,NULL,10,'2025-03-05 21:28:36','2025-04-02 12:04:02','thesis_pdfs/tduBJOq0aENHhznbox1v22vrU5BmDaHRKMqo3iOg.pdf',NULL,'[\"Teamprojekt\", \"Studienarbeit\", \"Bachelorthesis\", \"Masterthesis\"]'),(63,'Test paginate 1','Prof. Andreas Simon','Need more than 20 Thesises for this Test Need more than 20 Thesises for this Test Need more than 20 Thesises for this Test\r\nNeed more than 20 Thesises for this Test Need more than 20 Thesises f